Test for valid YAML front matter
```ts
import { test } from "@ende/front-matter/test";
import { assert } from "@ende/assert";

const result = test(
`---
title: Three dashes marks the spot
---
`);
assert(result);
```

Test for valid TOML front matter
```ts
import { test } from "@ende/front-matter/test";
import { assert } from "@ende/assert";

const result = test(
`---toml
title = 'Three dashes followed by format marks the spot'
---
`);
assert(result);
```

Test for valid JSON front matter
```ts
import { test } from "@ende/front-matter/test";
import { assert } from "@ende/assert";

const result = test(
`---json
{"title": "Three dashes followed by format marks the spot"}
---
`);
assert(result);
```

JSON front matter is not valid as YAML
```ts
import { test } from "@ende/front-matter/test";
import { assertFalse } from "@ende/assert";

const result = test(
`---json
{"title": "Three dashes followed by format marks the spot"}
---
`, ["yaml"]);
assertFalse(result);
```

Usage
```ts
import { extract } from "@ende/front-matter/any";
import { assertEquals } from "@ende/assert";

const output = `---json
{
  "title": "Three dashes marks the spot"
}
---
Hello, world!`;
const result = extract(output);
assertEquals(result, {
  frontMatter: '{\n  "title": "Three dashes marks the spot"\n}',
  body: "Hello, world!",
  attrs: { title: "Three dashes marks the spot" }
})
```

